    const fmt = (v, f) => f === 'm' ? (v >= 1e6 ? (v / 1e6).toFixed(2).replace(/\.?0+$/, '') + 'M' : Math.round(v / 1e3) + 'k') : Math.round(v).toLocaleString('en-US');
